    """record/replay 链路协商模式：校验 link-forward 配置与事件并执行仿真。

    语义同 link-forward 子命令；max_work 非 None 时全量语义校验后先按
    link-forward 公式无副作用预演，首次超过即抛 LinkForwardWorkLimit，
    不正式仿真。返回 (link-forward 结果 dict, observer 或 None)。
    """
    fwd_ports, caps, age, max_frame, delay = validate_link_forward_config(
        config
    )
    lf_events = validate_link_forward_events(events, fwd_ports)
    if max_work is not None:
        # 与 link-forward 入口同一公式：只计端口数与此前帧数，无副作用
        link_forward_work(fwd_ports, lf_events, max_work)
    observer = {} if observe else None
    result = link_forward(
        fwd_ports, caps, age, max_frame, delay, lf_events, observer=observer
    )
    return result, observer


def _run_link_state(config, events, observe, max_work=None):
    """record/replay 链路状态模式：校验 link-state 配置与事件并执行仿真。

    语义同 link-state 子命令；max_work 非 None 时全量语义校验后先按
    link-state 公式无副作用预演，首次超过即抛 LinkWorkLimit，不正式
    协商。返回 (link-state 结果 dict, observer 或 None)。
    """
    ports, delay = validate_link_state_config(config)
    ls_events = validate_link_state_events(events, ports)
    if max_work is not None:
        # 与 link-state 入口同一公式：每事件处理到期项前以 pending 数 Q
        # 累计 Q+1，无副作用
        link_state_work(ls_events, ports, delay, max_work)
    observer = {} if observe else None
    result = _link_state_run(ls_events, ports, delay, observer=observer)
    return result, observer


def _run_forward_static(config, events, observe, max_work=None):
    """record/replay forward-static 模式：校验 forward-static 配置与帧并
    执行仿真。

    语义同 forward-static 子命令；max_work 非 None 时（record/replay）
    全量语义校验后先按 forward-static 公式（逐帧累计 K+P+1，K 为老化前
    静态及动态表项数，P 为端口数）无副作用预演，首次超过即抛
    ForwardWorkLimit，不正式转发。返回 (forward-static 结果 dict,
    observer 或 None)；每帧恒 applied，version 恒 0，output 为对应
    results 项。
    """
    ports, age, static = validate_forward_static_config(config)
    frames = validate_frames_v2(events, ports)
    if max_work is not None:
        # 与 forward-static 入口同一公式：独立预置静态项的 FDB，无副作用
        forward_static_work(frames, ports, age, static, max_work)
    result = forward_static(frames, ports, age, static)
    observer = {} if observe else None
    if observer is not None:  # record/replay：逐帧记录 applied 与对应 results 项
        observer["items"] = [
            {
                "kind": "frame",
                "t": item["t"],
                "applied": True,
                "output": item,
            }
            for item in result["results"]
        ]
    return result, observer


def _run_forward_decode(config, events, observe, max_work=None):
    """record/replay forward-decode 模式：校验 forward-decode 配置与原始帧
    并执行仿真。

    语义同 forward-decode 子命令（CONFIG、FRAMES 校验与转发行为完全沿用）；
    max_work 非 None 时（record/replay）全量语义校验后先按逐帧 K+P+1
    （K 为本帧老化前动态 FDB 项数，P 为端口数；坏帧与准入拒绝也计费）
    无副作用预演，首次超过即抛 ForwardWorkLimit，不正式转发。返回
    (forward-decode 结果 dict, observer 或 None)；每帧恒 applied，version
    恒 0，output 为对应 results 项（键序 t,class,action,ports）。
    """
    ports, age, max_frame = validate_forward_check_config(config)
    frames = validate_forward_decode_frames(events, ports)
    if max_work is not None:
        # 与 forward-decode 转发同形的独立空 FDB 副本，无副作用
        forward_check_work(
            _decode_raw_frames(frames), ports, age, max_frame, max_work
        )
    result = forward_decode(frames, ports, age, max_frame)
    observer = {} if observe else None
    if observer is not None:  # record/replay：逐帧记录 applied 与对应 results 项
        observer["items"] = [
            {
                "kind": "frame",
                "t": item["t"],
                "applied": True,
                "output": item,
            }
            for item in result["results"]
        ]
    return result, observer


def _run_security_check(config, events, observe, max_work=None):
    """record/replay security-check 模式：校验 security-check 配置与事件并
    执行仿真。

    语义同 security-check 子命令；max_work 非 None 时（record）全量语义
    校验后先按 security-check 公式无副作用预演，首次超过即抛
    SecurityWorkLimit，不正式仿真。返回 (security-check 结果 dict,
    observer 或 None)。
    """
    (
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
        max_frame,
    ) = validate_security_check_config(config)
    link_ids = {link["id"] for link in links}
    check_events = validate_security_check_events(
        events, ports, link_ids, lags
    )
    if max_work is not None:
        # 与 security-check 入口同一公式：独立链路副本与空状态，无副作用
        security_check_work(
            bridges,
            links,
            delay,
            bridge,
            ports,
            age,
            storm,
            lags,
            acl,
            qos,
            security,
            max_frame,
            check_events,
            max_work,
        )
    observer = {} if observe else None
    result = forward_security_check(
        bridges,
        links,
        delay,
        bridge,
        ports,
        age,
        storm,
        lags,
        mirror,
        acl,
        qos,
        security,
        max_frame,
        check_events,
        observer=observer,
    )
    return result, observer


def _build_log_doc(config, events, items):
    """构造 LOG 文档（含 sha256）；records 与事件等长、同序。"""
    if len(events) != len(items):
        raise InvalidInput("bad log")
    mode = _log_mode(config)
    records = []
    # version 初值 0，取事件后值；安全模式每次 reload/rollback（无变化
    # 亦算）加 1，stp/环路模式链路 up 实际改变（applied）才加 1，链路协商
    # 模式仅 applied 链路项加 1（帧项恒 applied 但不计），链路状态模式
    # 仅 applied 项加 1，security-check 模式仅 applied 链路/成员项加 1
    # （帧与 service 恒 applied 但不计），forward-static 模式帧恒 applied
    # 且 version 恒 0
    version = 0
    for event, observed in zip(events, items):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log")
        if mode in ("stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode == "link_forward":
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode == "security_check":
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        records.append(
            {
                "t": event["t"],
                "version": version,
                "event": _canonical(event),
                "applied": observed["applied"],
                "output": observed["output"],
            }
        )
    doc = {
        "schema": RECORD_SCHEMA,
        "config": _canonical(config),
        "records": records,
    }
    doc["sha256"] = hashlib.sha256(_log_prefix_bytes(doc)).hexdigest()
    return doc


def _log_prefix_bytes(doc):
    """sha256 摘要文本：schema,config,records 规范序列化后含 LF。"""
    prefix = {
        "schema": doc["schema"],
        "config": doc["config"],
        "records": doc["records"],
    }
    return (
        json.dumps(prefix, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _log_bytes(doc):
    ordered = {key: doc[key] for key in LOG_KEYS}
    return (
        json.dumps(ordered, ensure_ascii=False, separators=(",", ":")) + "\n"
    ).encode("utf-8")


def _assert_canonical_order(value):
    """config/event 内对象键须递归按 Unicode 码点升序，数组保序。"""
    if isinstance(value, dict):
        keys = list(value)
        if keys != sorted(keys):
            raise InvalidInput("bad log key order")
        for item in value.values():
            _assert_canonical_order(item)
    elif isinstance(value, list):
        for item in value:
            _assert_canonical_order(item)


def _json_equal(a, b):
    """JSON 值深比较；bool 不与 int 混同，键序无关，数组保序。"""
    if isinstance(a, bool) or isinstance(b, bool):
        return isinstance(a, bool) and isinstance(b, bool) and a == b
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(
            _json_equal(a[key], b[key]) for key in a
        )
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(
            _json_equal(x, y) for x, y in zip(a, b)
        )
    if a is None or b is None:
        return a is None and b is None
    return type(a) is type(b) and a == b


def _validate_log_shape(log):
    """严格校验 LOG 字段、类型、键序；不含语义重放。"""
    if not isinstance(log, dict) or list(log) != list(LOG_KEYS):
        raise InvalidInput("bad log")
    if not _is_int(log["schema"]) or log["schema"] != RECORD_SCHEMA:
        raise InvalidInput("bad log schema")
    config = log["config"]
    if not isinstance(config, dict):
        raise InvalidInput("bad log config")
    _assert_canonical_order(config)
    records = log["records"]
    if not isinstance(records, list):
        raise InvalidInput("bad log records")
    for record in records:
        if not isinstance(record, dict) or list(record) != list(RECORD_KEYS):
            raise InvalidInput("bad log record")
        if not _is_int(record["t"]) or record["t"] < 0:
            raise InvalidInput("bad log t")
        if not _is_int(record["version"]) or record["version"] < 0:
            raise InvalidInput("bad log version")
        event = record["event"]
        if not isinstance(event, dict):
            raise InvalidInput("bad log event")
        _assert_canonical_order(event)
        _event_kind(event)
        if not isinstance(record["applied"], bool):
            raise InvalidInput("bad log applied")
        if record["output"] is not None and not isinstance(
            record["output"], dict
        ):
            raise InvalidInput("bad log output")
    digest = log["sha256"]
    if not isinstance(digest, str) or _HEX64_RE.fullmatch(digest) is None:
        raise InvalidInput("bad log sha256")


def _verify_records(log, events, items):
    """重放后逐项核对 t/version/event/applied/output。"""
    records = log["records"]
    if len(records) != len(items):
        raise InvalidInput("bad log records")
    mode = _log_mode(log["config"])
    version = 0
    for event, observed, record in zip(events, items, records):
        kind = _event_kind(event)
        if kind != observed["kind"]:
            raise InvalidInput("bad log record")
        if mode in ("stp", "loop"):
            if observed["applied"]:
                version += 1
        elif mode == "link_forward":
            if kind == "link" and observed["applied"]:
                version += 1
        elif mode == "link_state":
            if observed["applied"]:
                version += 1
        elif mode == "security_check":
            if kind in ("link", "member") and observed["applied"]:
                version += 1
        elif kind in ("reload", "rollback"):
            version += 1
        if record["t"] != event["t"]:
            raise InvalidInput("bad log t")
        if record["version"] != version:
            raise InvalidInput("bad log version")
        if not _json_equal(record["event"], _canonical(event)):
            raise InvalidInput("bad log event")
        if record["applied"] is not observed["applied"]:
            raise InvalidInput("bad log applied")
        if not _json_equal(record["output"], observed["output"]):
            raise InvalidInput("bad log output")


def _atomic_write(path, payload):
    """同目录临时文件 + os.replace 原子写入；失败不改动目标。"""
    directory = os.path.dirname(os.path.abspath(path))
    fd, tmp_path = tempfile.mkstemp(prefix=".switch-log-", dir=directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except OSError:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


def _cmd_record(
    config_path,
    events_path,
    log_path,
    max_events,
    max_log_bytes,
    max_config_bytes,
    max_events_bytes,
    max_output_bytes,
    max_record_work,
):
    try:
        with open(config_path, "rb") as config_handle, open(
            events_path, "rb"
        ) as events_handle:
            # 两文件均可读后，先判 CONFIG 原始字节，再判 EVENTS 原始字节
            config_raw = _read_limited(config_handle, max_config_bytes)
            if config_raw is None:
                _fail("config_limit")
                return 5
            events_raw = _read_limited(events_handle, max_events_bytes)
            if events_raw is None:
                _fail("events_limit")
                return 5
    except OSError:
        _fail("file_not_found")
        return 3
    try:
        # 事件上界先于解析与预演判定；超限时绝不触碰 LOG
        events_preview = parse_json(events_raw)
        if isinstance(events_preview, list) and len(events_preview) > max_events:
            _fail("event_limit")

            _fail("event_limit")
            return 5
        # 先无副作用预演：解析、全部校验与各重载点检测均在内存完成；
        # 工作量预演在语义校验后、正式仿真与 LOG 构造前，超限绝不触碰 LOG
        config = parse_json(config_raw)
        events = events_preview
        mode = _log_mode(config)
        if mode == "stp":
            result, observer = _run_stp(
                config, events, True, max_record_work
            )
        elif mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_record_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_record_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_record_work
            )
        elif mode == "forward_static":
            result, observer = _run_forward_static(
                config, events, True, max_record_work
            )
        elif mode == "forward_decode":
            result, observer = _run_forward_decode(
                config, events, True, max_record_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_record_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_record_work
            )
        doc = _build_log_doc(config, events, observer["items"])
        payload = _log_bytes(doc)
        # 字节上界（含末尾 LF）在写入前判定；等于上限合法
        if len(payload) > max_log_bytes:
            _fail("log_limit")
            return 5
        # 输出上界在 log_limit 之后、原子写 LOG 之前判定；超限时绝不触碰 LOG
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
        _atomic_write(log_path, payload)  # 成功后才原子写 LOG
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        ForwardWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        SecurityWorkLimit,
    ):
        _fail("record_work_limit")
        return 5
    except OSError:
        _fail("file_not_found")
        return 3
    sys.stdout.buffer.write(output)
    return 0


def _cmd_replay(
    log_path,
    max_events,
    max_log_bytes,
    max_output_bytes,
    max_replay_work,
    expected_sha256=None,
):
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    # 字节上界先判定（分块读取、超限即停，含末尾 LF）
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        log = parse_json(log_raw)  # 全量校验先于重放
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        # 外部承诺先于事件数与一切语义重放：EXPECTED 须是调用方从成功
        # record 产物顶层 sha256 独立保存的值，绝不取自待重放 LOG。仅改
        # 帧并重算 LOG 内摘要的等价重写虽能通过内部自洽校验，仍因外部
        # 承诺不符在此失败（stdout 空、LOG 不动）
        if expected_sha256 is not None and expected_sha256 != log["sha256"]:
            raise InvalidInput("bad log sha256")
        config = log["config"]
        events = [record["event"] for record in log["records"]]
        # records 上界在解析校验后、重放前判定
        if len(log["records"]) > max_events:
            _fail("event_limit")
            return 5
        # 状态语义校验后先按 record 同一公式无副作用预演；首次超限即停止，
        # 不正式重放，LOG 保持不动
        mode = _log_mode(config)
        if mode == "stp":
            result, observer = _run_stp(
                config, events, True, max_replay_work
            )
        elif mode == "loop":
            result, observer = _run_loop_detect(
                config, events, True, max_replay_work
            )
        elif mode == "link_forward":
            result, observer = _run_link_forward(
                config, events, True, max_replay_work
            )
        elif mode == "link_state":
            result, observer = _run_link_state(
                config, events, True, max_replay_work
            )
        elif mode == "forward_static":
            result, observer = _run_forward_static(
                config, events, True, max_replay_work
            )
        elif mode == "forward_decode":
            result, observer = _run_forward_decode(
                config, events, True, max_replay_work
            )
        elif mode == "security_check":
            result, observer = _run_security_check(
                config, events, True, max_replay_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_replay_work
            )
        _verify_records(log, events, observer["items"])
        # 重放重建的 LOG 须与原文件逐字节一致（含 sha256 与 LF）
        rebuilt = _build_log_doc(config, events, observer["items"])
        if _log_bytes(rebuilt) != log_raw:
            raise InvalidInput("bad log")
        # 输出上界在全部日志语义与重放核对成功后判定；LOG 保持不动
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        ForwardWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        SecurityWorkLimit,
    ):
        _fail("replay_work_limit")
        return 5
    sys.stdout.buffer.write(output)
    return 0


CONFIG_DIFF_MAX_INPUT_BYTES = 1024 * 1024


def _json_pointer_token(token):
    """RFC6901 reference token 转义：~ 编码为 ~0，/ 编码为 ~1。"""
    return token.replace("~", "~0").replace("/", "~1")


def _diff_collect(old, new, path, changes):
    """按键序无关契约收集 OLD、NEW 的差异项到 changes。

    对象递归，键按 Unicode 码点升序深度优先；数组整体比较且顺序敏感，
    整组不同仅出一项；标量按 JSON 类型与值比较。path 为 RFC6901 JSON
    Pointer（根为 ""）。仅不同的数组或标量（及缺失对象键）生成项。
    """
    if isinstance(old, dict) and isinstance(new, dict):
        for key in sorted(set(old) | set(new)):
            child = path + "/" + _json_pointer_token(key)
            if key in old and key in new:
                _diff_collect(old[key], new[key], child, changes)
            elif key in old:
                # 仅旧侧存在；合法 port-security 配置各层键集固定，不会到达
                changes.append(
                    {"path": child, "before": _canonical(old[key]),
                     "after": None}
                )
            else:
                changes.append(
                    {"path": child, "before": None,
                     "after": _canonical(new[key])}
                )
        return
    # 两数组整体（顺序敏感）、两标量（JSON 类型+值）或类别不一致：
    # 不同即整值一项，前后值按同一规则规范化
    if not _json_equal(old, new):
        changes.append(
            {"path": path, "before": _canonical(old),
             "after": _canonical(new)}
        )


def _diff_size(value):
    """工作量公式的 S：标量 1；数组 1+各元素 S 之和；
    对象 1+键数+各值 S 之和。"""
    if isinstance(value, dict):
        return 1 + len(value) + sum(_diff_size(item) for item in value.values())
    if isinstance(value, list):
        return 1 + sum(_diff_size(item) for item in value)
    return 1

def validate_stp_decode_events(events, ports, link_ids):
    """stp-decode 事件：原链路项与 t/port/data 原始帧按 t 非降混合。

    链路项沿用 forward-stp；帧子序列复用 forward-decode 全量校验
    （hex、最短长度、单层 8100、双标签拒绝、MAC 合法性），再在混合序上
    重放跨类型的 t 非降。
    """
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    frame_docs = []
    frame_positions = set()
    for index, event in enumerate(events):
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_DECODE_FRAME_KEYS:
            frame_docs.append(event)
            frame_positions.add(index)
        elif keys != STP_EVENT_KEYS:
            raise InvalidInput("bad event")
    # 帧子序列的外壳（hex、8100、双标签）与 MAC 规则同 forward-decode
    checked_frames = validate_forward_decode_frames(frame_docs, ports)
    raw_by_pos = dict(zip(sorted(frame_positions), checked_frames))
    result = []
    prev_t = None
    for index, event in enumerate(events):
        t = event["t"]
        if not _is_int(t) or t < 0:
            raise InvalidInput("bad t")
        if prev_t is not None and t < prev_t:  # 链路与帧混合序上 t 非降
            raise InvalidInput("t not monotonic")
        prev_t = t
        if index in raw_by_pos:
            _, port_name, raw = raw_by_pos[index]
            result.append(("frame", t, port_name, raw))
        else:
            lid = event["id"]
            up = event["up"]
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
    return result


