def stp(bridges, links, delay, events, max_work=None):
    """STP 公共入口：精确签名不变，返回 {"results": [...]}，无 observer 形参。

    record/replay 所需的逐事件观察逻辑封装在内部 _stp_run 中。
    """
    return _stp_run(bridges, links, delay, events, max_work, observer=None)


def _stp_run(bridges, links, delay, events, max_work=None, observer=None):
    by_id = {link["id"]: link for link in links}
    B = len(bridges)
    L = len(links)

    def up_count():
        return sum(1 for link in links if link["up"])

    def work_for(up):
        return B + L + 2 * up

    # 仅当 up 链路集合改变时才真正收敛；幂等事件复用缓存结果。
    # 先以独立链路状态无副作用预演，累计工作量超限即在仿真前报错。
    # 工作量初值 B+L+2U（t=0 收敛）；每次 up 实际改变后按新 U 再加同式，
    # 幂等事件不加；等于上限合法，首次超过即抛 StpWorkLimit。
    work = 0
    up = up_count()
    work += work_for(up)  # 初始 t=0 收敛
    sim_up = {lid: link["up"] for lid, link in by_id.items()}
    for _t, lid, new_up in events:
        if sim_up[lid] != new_up:
            sim_up[lid] = new_up
            up += 1 if new_up else -1
            work += work_for(up)
    if max_work is not None and work > max_work:
        raise StpWorkLimit

    if observer is not None:  # record：逐事件记录 applied 与事件后快照
        observer["items"] = []
    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    results = []
    cached = None  # 最近一次实际收敛的 (root_of, cost, roles)

    def snapshot(t):
        nonlocal cached
        if cached is None:
            cached = stp_converge(bridges, links)
        root_of, cost, roles = cached
        for name in bridges:
            for port, role in roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in roles[name].items():
                previous[(name, port)] = role
        entry = {"t": t, "bridges": []}
        for name in bridges:
            ports = []
            for port in sorted(roles[name]):
                role = roles[name][port]
                if role in STP_TIMED_ROLES:
                    elapsed = t - since[(name, port)]
                    if elapsed < delay:
                        state = "discarding"
                    elif elapsed < 2 * delay:
                        state = "learning"
                    else:
                        state = "forwarding"
                else:
                    state = "discarding"
                ports.append({"name": port, "role": role, "state": state})
            entry["bridges"].append(
                {
                    "name": name,
                    "root": root_of[name],
                    "cost": cost[name],
                    "ports": ports,
                }
            )
        results.append(entry)

    snapshot(0)  # 初始 t=0 快照不写入记录
    for t, lid, new_up in events:
        applied = by_id[lid]["up"] != new_up  # up 实际改变才 applied
        if applied:
            by_id[lid]["up"] = new_up
            cached = None
        snapshot(t)
        if observer is not None:
            observer["items"].append(
                {"kind": "link", "t": t, "applied": applied,
                 "output": results[-1]}
            )
    return {"results": results}


def validate_loop_detect_config(config):
    if not isinstance(config, dict) or frozenset(config) != LOOP_CONFIG_KEYS:
        raise InvalidInput("bad config")
    vlans = config["vlans"]
    if (
        not isinstance(vlans, list)
        or not vlans
        or not all(_is_int(v) and 1 <= v <= 4094 for v in vlans)
        or any(vlans[i] >= vlans[i + 1] for i in range(len(vlans) - 1))
    ):
        raise InvalidInput("bad vlans")
    # 链路项在 stp 契约上增加 vlans：CONFIG.vlans 的严格递增非空子集
    raw_links = config["links"]
    if not isinstance(raw_links, list) or any(
        not isinstance(link, dict) or frozenset(link) != LOOP_LINK_KEYS
        for link in raw_links
    ):
        raise InvalidInput("bad link")
    stp_config = {
        "bridges": config["bridges"],
        "links": [
            {
                "id": link["id"],
                "x": link["x"],
                "y": link["y"],
                "cost": link["cost"],
                "up": link["up"],
            }
            for link in raw_links
        ],
        "delay": 1,
    }
    bridges, links, _delay = validate_stp_config(stp_config)
    vlan_set = set(vlans)
    for link, raw_link in zip(links, config["links"]):
        link_vlans = raw_link["vlans"]
        if (
            not isinstance(link_vlans, list)
            or not link_vlans
            or not all(_is_int(v) and v in vlan_set for v in link_vlans)
            or any(
                link_vlans[i] >= link_vlans[i + 1]
                for i in range(len(link_vlans) - 1)
            )
        ):
            raise InvalidInput("bad link vlans")
        link["vlans"] = link_vlans
    return bridges, links, vlans


def loop_detect(links, vlans, events, max_work=None, observer=None):
